            </view>
          </view>
        </view>
        <view v-if="recommendations.loading" class="state" role="status">正在加载商品推荐…</view>
        <view v-if="recommendations.error" class="state error" role="alert">{{ recommendations.error }}<button :disabled="recommendations.loading || recommendations.navigating" @tap="recommendations.retry">重试商品推荐</button></view>
        <view v-if="recommendations.mediaExpired" class="state">商品图片已过期，请刷新商品推荐</view>
        <button v-if="recommendations.hasMore && !recommendations.error" class="load-more" :disabled="recommendations.loading || recommendations.navigating" @tap="recommendations.load(true)">加载更多推荐</button>
        <view v-if="recommendations.page && !recommendations.hasMore && !recommendations.loading && !recommendations.error" class="state">{{ recommendations.items.length ? '没有更多推荐了' : '暂无推荐商品' }}</view>
        <button v-if="recommendations.items.length || recommendations.error || recommendations.mediaExpired" class="load-more" :disabled="recommendations.loading || recommendations.navigating" @tap="recommendations.refresh">刷新商品推荐</button>
      </view>
      <view v-if="playing" class="video-overlay" @tap="closeVideo"><view class="video-panel" @tap.stop><video :key="playing.id" class="player" :src="media(playing.video_url)" :poster="media(playing.image)" :controls="true" :autoplay="false" @error="playbackFailed" /><view class="playing-title">{{ playing.desc }}</view><button @tap="closeVideo">关闭视频</button></view></view>
    </view>
    <DiySuspendedNavigation v-if="!managing" />
  </ThemePage>
</template>
<script setup lang="ts">
